const now = new Date();
const currentDay = now.toLocaleString('en-US', { weekday: 'long' });
const currentTime = now.getHours() * 60 + now.getMinutes();

// Helper to parse time like '9:00 AM'
function parseTime(timeStr) {
  const [time, modifier] = timeStr.split(' ');
  let [hours, minutes] = time.split(':').map(Number);
  if (modifier === 'PM' && hours !== 12) hours += 12;
  if (modifier === 'AM' && hours === 12) hours = 0;
  return hours * 60 + (minutes || 0);
}

const upcoming = items
  .filter(item => item.json.Day === currentDay)
  .map(item => {
    const [startStr] = item.json['Time Slot'].split('-').map(s => s.trim());
    const startMinutes = parseTime(startStr);
    return { ...item.json, startMinutes };
  })
  .filter(i => i.startMinutes > currentTime)
  .sort((a, b) => a.startMinutes - b.startMinutes)[0];

return upcoming ? [{ json: upcoming }] : [];
